// Generated from dialogues/animals/*.json and dialogues/branches.json. Run node dialogues/build-bundle.cjs after edits.
window.FARM_DIALOGUES = {"animals":{"cat":{"name":"貓","nextCharacter":"crow","normal":[{"pages":["貓咪用爪子撥弄一顆鈕扣，鈕扣滾進草縫，牠便假裝自己本來就想看草。「喵，別笑，我正在巡邏。」","牠坐直身子：「我聽了貝克的故事，也有點怕。不過還有繃帶要整理。忙一件能幫忙的小事，心就不會一直亂跑。」"]}],"panicked":[{"pages":["貓咪縮在木箱後，只露出一雙眼睛。「貝克說狼會跳得很高。這個箱子，是不是也不夠高？」","你沒有把牠拉出來，只蹲在旁邊。過了一會兒，一隻小爪子輕輕碰到你的鞋。"]}],"comforted":{"pages":["你慢慢摸摸牠的頭，等急促的呼吸變得平穩。牠看向你：「謝謝你願意等。我們再把事情從頭想一遍吧。」","牠坐直身子：「我聽了貝克的故事，也有點怕。不過還有繃帶要整理。忙一件能幫忙的小事，心就不會一直亂跑。」"]},"injured":{"pages":["貓蜷在草地上，試著站起來，又輕輕坐回去。「這次真的受傷了……你看得見我嗎？」","你蹲下來，讓牠知道有人陪著。「我們回紅農舍上藥。路上慢慢走，其他的事等安全了再說。」"]},"post_rescue":{"pages":["貓咪裹著繃帶，仍記得替你把衣角理平。「喵，這是謝禮。你先坐下，我聽得見你也喘得很厲害。」","牠望著門外：「待會兒也去看看別的傷患吧。害怕時有人陪，受傷時有人找，農舍才算是家。」"]},"rumorResponse":{"pages":["{name}的尾巴一下膨成毛刷：「狼把你傷成這樣？那我的爪子會不會太小了？」","牠跳上窗臺，緊盯東門。窗臺下的繃帶被風吹開，像一條沒人收好的白色小路。"]},"afterTruth":[{"pages":["貓望向正在道歉的貝克：「原來那條腿是跌進泥坑傷的。我剛才相信了，還把自己嚇得團團轉。」","你們一起把聽說的話和查到的事分開記。風又吹動草尖，大家重新聽見了農場原本的聲音。"]}]},"chicken":{"name":"雞","nextCharacter":"duck","normal":[{"pages":["雞媽媽咯咯叫，小雞們跟著踩過一片片落葉，像在翻金黃色的書頁。「這是我們的早餐散步！」","牠忽然壓低聲音：「可是貝克今天說了狼的事。我想保護孩子，又不知道該相信哪一條路安全。你有新消息，記得慢慢告訴我。」"]}],"panicked":[{"pages":["雞媽媽把同一隻小雞數了三次。「是不是少了一個？貝克說狼來了，我一緊張就數亂了！」","你陪牠從第一隻重新數起。牠望著你，聲音小了一點：「等我不發抖，就能把昨晚的聲音說清楚。」"]}],"comforted":{"pages":["你慢慢摸摸牠的頭，等急促的呼吸變得平穩。牠看向你：「謝謝你願意等。我們再把事情從頭想一遍吧。」","牠忽然壓低聲音：「可是貝克今天說了狼的事。我想保護孩子，又不知道該相信哪一條路安全。你有新消息，記得慢慢告訴我。」"]},"injured":{"pages":["雞蜷在草地上，試著站起來，又輕輕坐回去。「這次真的受傷了……你看得見我嗎？」","你蹲下來，讓牠知道有人陪著。「我們回紅農舍上藥。路上慢慢走，其他的事等安全了再說。」"]},"post_rescue":{"pages":["繃帶包好後，雞媽媽第一句還是：「孩子們呢？」看見同伴都在，牠才把頭安心地靠下。","「謝謝你。南邊廢果園有壓倒的草，你可以去查看。這次請把真的看見什麼，帶回來告訴我們。」"]},"rumorResponse":{"pages":["{name}立刻張開翅膀：「快躲進來！貝克都和狼打架了，外面一定不能待！」","小雞不明白出了什麼事，只跟著大夥擠成一團。原本的咯咯歌，一下變成了急促的叫聲。"]},"afterTruth":[{"pages":["雞望向正在道歉的貝克：「原來那條腿是跌進泥坑傷的。我剛才相信了，還把自己嚇得團團轉。」","你們一起把聽說的話和查到的事分開記。風又吹動草尖，大家重新聽見了農場原本的聲音。"]}]},"cow":{"name":"牛","nextCharacter":"horse","normal":[{"pages":["乳牛把一撮乾草推到你面前，鈴鐺叮噹響。「忙了一圈，歇歇腿吧。從前貝克替大家分牧草，我就知道牠腦筋轉得快。」","牠望向貝克抬起的腿：「我願意照顧牠，可是越聽牠的故事，我越擔心小夥伴。你巡路時，也能看看北邊嗎？」"]}],"panicked":[{"pages":["乳牛不停用鼻尖數身邊的同伴。「一、二、三……別走散。貝克說狼要來，我不能少照顧一個。」","鈴鐺撞得叮叮噹噹。你伸出手，牠小聲說：「先陪我把呼吸放慢，再陪我想想，好不好？」"]}],"comforted":{"pages":["你慢慢摸摸牠的頭，等急促的呼吸變得平穩。牠看向你：「謝謝你願意等。我們再把事情從頭想一遍吧。」","牠望向貝克抬起的腿：「我願意照顧牠，可是越聽牠的故事，我越擔心小夥伴。你巡路時，也能看看北邊嗎？」"]},"injured":{"pages":["牛蜷在草地上，試著站起來，又輕輕坐回去。「這次真的受傷了……你看得見我嗎？」","你蹲下來，讓牠知道有人陪著。「我們回紅農舍上藥。路上慢慢走，其他的事等安全了再說。」"]},"post_rescue":{"pages":["紅農舍裡，鈴鐺終於安靜了。乳牛把頭輕靠在乾草上：「原來被照顧的時候，心裡是這樣暖的。」","牠提醒你：「北渠的風裡有狼味。這是值得查的地方，別因為大家都看東門，就把北邊忘了。」"]},"rumorResponse":{"pages":["{name}把鈴鐺按住，生怕響聲引來狼。「連你都受傷了？孩子們，快跟著我！」","牠們排成歪歪的一列，往東邊張望。原本悠閒的嚼草聲，變成了急促的呼吸聲。"]},"afterTruth":[{"pages":["牛望向正在道歉的貝克：「原來那條腿是跌進泥坑傷的。我剛才相信了，還把自己嚇得團團轉。」","你們一起把聽說的話和查到的事分開記。風又吹動草尖，大家重新聽見了農場原本的聲音。"]}]},"crow":{"name":"烏鴉","nextCharacter":"sparrow","normal":[{"pages":["烏鴉倒掛在枝頭，黑羽毛被晨光擦得亮亮的。「嘎！你也聽到羊狼大戰了？那個故事可把一個大泥坑忘得乾乾淨淨。」","牠翻身站好：「我看見貝克怎麼傷的。我願意說，但別只顧著笑牠——先問信鴿昨晚的時間，再來把事情拼完整。」"]}],"panicked":[{"pages":["烏鴉張開翅膀，先看清四周的路。「嘎，別只顧著跟著傳言亂跑！我知道貝克跌進泥坑的事，等大家站穩，我就說。」","牠飛到安全的枝頭，回望地上的同伴：「我也會擔心大家。但擔心的時候，更得把親眼看見的事說清楚。」"]}],"comforted":{"pages":["烏鴉倒掛在枝頭，黑羽毛被晨光擦得亮亮的。「嘎！你也聽到羊狼大戰了？那個故事可把一個大泥坑忘得乾乾淨淨。」","牠翻身站好：「我看見貝克怎麼傷的。我願意說，但別只顧著笑牠——先問信鴿昨晚的時間，再來把事情拼完整。」"]},"injured":{"pages":["烏鴉想展翅，卻痛得縮回來。牠收起平日的笑聲：「今天不能飛了。先讓我在安全的地方休息。」","你蹲下來，讓牠知道有人陪著。「我們回紅農舍上藥。路上慢慢走，其他的事等安全了再說。」"]},"post_rescue":{"pages":["烏鴉的翅膀包上繃帶，像披了一小片雲。「嘎，今天先讓狼得意一下。我飛不穩，可不會逞強去挑戰牠。」","牠湊近你：「北渠有狼爪印，但貝克是自己跌倒。兩件事都要記得。謝謝你救我，等翅膀好了，我再上天空幫忙。」"]},"rumorResponse":{"pages":["{name}沒有縮起翅膀：「嘎！先去聽烏鴉說牠昨夜親眼看見的事。你的傷是真的，跟狼打架可得有人看見才算！」","貝克支支吾吾。枝頭傳來烏鴉清亮的聲音：「我看見你滑進泥坑啦！狼又不會飛，真來抓我，我飛高一點就好。你別把跌倒編成打架！」"]},"afterTruth":[{"pages":["烏鴉站在枝頭，沒有再笑貝克的腿。「嘎，肯把真話說出來，也需要一點勇氣。」","牠忽然對森林喊：「狼呀，你還是不會飛吧！」說完一振翅，飛到高高的樹梢。這一回，地上的同伴也安心地笑了。"]}]},"dog":{"name":"狗","nextCharacter":"cat","normal":[{"pages":["托托在草地上畫了一串腳印，又回頭把最小的一個聞了聞。「這是我早上留下的。你看，鼻子也能讀故事！」","牠望著貝克：「牠以前替大家想辦法，我很信任牠。可是再信任的朋友，也可能記錯。我想一邊聽，一邊查。」"]}],"panicked":[{"pages":["托托對著搖晃的草叢汪汪叫，叫完才發現是一片落葉。「我以為又是狼……貝克說的畫面一直跑進腦袋裡。」","牠把頭靠向你的手心：「摸摸我吧。我冷靜下來，鼻子才聞得清楚。」"]}],"comforted":{"pages":["你慢慢摸摸牠的頭，等急促的呼吸變得平穩。牠看向你：「謝謝你願意等。我們再把事情從頭想一遍吧。」","牠望著貝克：「牠以前替大家想辦法，我很信任牠。可是再信任的朋友，也可能記錯。我想一邊聽，一邊查。」"]},"injured":{"pages":["狗蜷在草地上，試著站起來，又輕輕坐回去。「這次真的受傷了……你看得見我嗎？」","你蹲下來，讓牠知道有人陪著。「我們回紅農舍上藥。路上慢慢走，其他的事等安全了再說。」"]},"post_rescue":{"pages":["托托舔舔繃帶旁的毛，輕輕搖尾巴。「你沒有丟下我，真好。等傷口好了，我還要陪大家巡路。」","牠提醒你西門下的狼味：「可以先請健康的同伴留意那裡。守住農場，需要大家一起幫忙。」"]},"rumorResponse":{"pages":["{name}的尾巴慢慢垂下：「你竟然和狼打了一夜？汪，那今晚一定很危險！」","牠急著去提醒別人，連西門下那股新鮮氣味也差點漏掉了。擔心把鼻子裡的線索，擠到了腦袋後面。"]},"afterTruth":[{"pages":["狗望向正在道歉的貝克：「原來那條腿是跌進泥坑傷的。我剛才相信了，還把自己嚇得團團轉。」","你們一起把聽說的話和查到的事分開記。風又吹動草尖，大家重新聽見了農場原本的聲音。"]}]},"duck":{"name":"鴨","nextCharacter":"goose","normal":[{"pages":["鴨子在水邊追自己的倒影。牠往左，倒影也往左；牠一拍水，兩隻鴨子就碎成好多片亮光。","「昨夜的影子可沒有這麼可愛。」牠靠近你，「聽完貝克的話，我越想越怕。你能幫我把昨晚的事，從頭想一遍嗎？」"]}],"panicked":[{"pages":["鴨子把嘴藏在翅膀裡，聲音悶悶的。「貝克說有狼，我昨晚又看見怪影……是不是我一游泳，牠就會來？」","你讓一片葉子漂過水面。牠偷偷抬頭：「小小的葉子，也會有長長的影子呀。讓我再想想。」"]}],"comforted":{"pages":["你慢慢摸摸牠的頭，等急促的呼吸變得平穩。牠看向你：「謝謝你願意等。我們再把事情從頭想一遍吧。」","「昨夜的影子可沒有這麼可愛。」牠靠近你，「聽完貝克的話，我越想越怕。你能幫我把昨晚的事，從頭想一遍嗎？」"]},"injured":{"pages":["鴨蜷在草地上，試著站起來，又輕輕坐回去。「這次真的受傷了……你看得見我嗎？」","你蹲下來，讓牠知道有人陪著。「我們回紅農舍上藥。路上慢慢走，其他的事等安全了再說。」"]},"post_rescue":{"pages":["鴨子坐在乾草上，腳掌包得像一片白雲。「今天不能下水了。你能替我看看池塘嗎？」","牠補上一句：「如果看見影子，先看看岸上是什麼。我昨晚只看影子，就把自己嚇壞了。」"]},"rumorResponse":{"pages":["{name}啪嗒啪嗒地退到岸邊：「怪不得我昨晚看見大影子！一定就是傷你的狼！」","一個沒看清的影子，接上一段沒查過的故事，忽然就變成了可怕的大怪物。鴨子再也不敢回頭看水面。"]},"afterTruth":[{"pages":["鴨望向正在道歉的貝克：「原來那條腿是跌進泥坑傷的。我剛才相信了，還把自己嚇得團團轉。」","你們一起把聽說的話和查到的事分開記。風又吹動草尖，大家重新聽見了農場原本的聲音。"]}]},"goose":{"name":"鵝","nextCharacter":"crow","normal":[{"pages":["大鵝正把池邊的小石子推成一排，像一條給小鴨走的橋。「慢慢走，別把腳踩進軟泥裡。」","牠抬頭看你：「貝克受傷後，大家都來問我池塘安不安全。我也聽了牠的故事，可我想先把這一段岸邊看好。」"]}],"panicked":[{"pages":["大鵝用翅膀攔住岸邊的路。「別過去！貝克說了……貝克到底說狼在東門，還是在池塘？」","牠想不起原話，卻記得害怕的感覺。你輕輕摸牠的頭：「我們可以一件一件問清楚。」"]}],"comforted":{"pages":["你慢慢摸摸牠的頭，等急促的呼吸變得平穩。牠看向你：「謝謝你願意等。我們再把事情從頭想一遍吧。」","牠抬頭看你：「貝克受傷後，大家都來問我池塘安不安全。我也聽了牠的故事，可我想先把這一段岸邊看好。」"]},"injured":{"pages":["鵝蜷在草地上，試著站起來，又輕輕坐回去。「這次真的受傷了……你看得見我嗎？」","你蹲下來，讓牠知道有人陪著。「我們回紅農舍上藥。路上慢慢走，其他的事等安全了再說。」"]},"post_rescue":{"pages":["大鵝靠在農舍門邊，終於把緊繃的脖子放鬆。「原來守路的也會需要別人守著。謝謝你。」","牠望向池塘：「我想回去陪鴨子。等我好些，我們一起看岸上的腳印，不再只盯著晃動的影子。」"]},"rumorResponse":{"pages":["{name}伸長脖子：「連你也打不過？那我得把水邊的同伴都叫回來！」","牠把傳言一聲聲喊出去，越喊越響。池塘其實還和剛才一樣安靜，只是大家已經聽不見水聲了。"]},"afterTruth":[{"pages":["鵝望向正在道歉的貝克：「原來那條腿是跌進泥坑傷的。我剛才相信了，還把自己嚇得團團轉。」","你們一起把聽說的話和查到的事分開記。風又吹動草尖，大家重新聽見了農場原本的聲音。"]}]},"horse":{"name":"馬","nextCharacter":"dog","normal":[{"pages":["馬兒低頭，讓一隻蝴蝶停在鼻尖。牠憋了好久，終於打出一個大噴嚏。蝴蝶飛走了，你們一起笑起來。","「我跑得快，貝克想得快，以前我們常常一起幫忙。」牠輕踏草地，「現在牠說狼很可怕，我想幫忙，腿卻總是不由自主地想跑。」"]}],"panicked":[{"pages":["馬兒繞著同一棵樹打轉。「東門，還是農舍？貝克說得太急，我只記得狼的牙齒！」","你站在牠看得見的地方，慢慢揮手。馬兒終於停住：「先別催我。我想把心跳找回來。」"]}],"comforted":{"pages":["你慢慢摸摸牠的頭，等急促的呼吸變得平穩。牠看向你：「謝謝你願意等。我們再把事情從頭想一遍吧。」","「我跑得快，貝克想得快，以前我們常常一起幫忙。」牠輕踏草地，「現在牠說狼很可怕，我想幫忙，腿卻總是不由自主地想跑。」"]},"injured":{"pages":["馬蜷在草地上，試著站起來，又輕輕坐回去。「這次真的受傷了……你看得見我嗎？」","你蹲下來，讓牠知道有人陪著。「我們回紅農舍上藥。路上慢慢走，其他的事等安全了再說。」"]},"post_rescue":{"pages":["馬兒的傷腿包好了，牠試著輕輕落蹄。「這次你跑來救我，等我好些，也換我替大家跑腿。」","牠請你留意西門下面被刨鬆的土：「找狗聞聞看吧。我們把路看清楚，才知道往哪裡跑。」"]},"rumorResponse":{"pages":["{name}急急倒退兩步：「你的腿是為了保護我們傷的？那我更要跑快一點，帶大家逃走！」","噠噠噠，蹄聲越響，旁邊的動物越慌。誰也沒來得及問：昨晚，究竟有誰看見那場打架？"]},"afterTruth":[{"pages":["馬望向正在道歉的貝克：「原來那條腿是跌進泥坑傷的。我剛才相信了，還把自己嚇得團團轉。」","你們一起把聽說的話和查到的事分開記。風又吹動草尖，大家重新聽見了農場原本的聲音。"]}]},"pig":{"name":"豬","nextCharacter":"dog","normal":[{"pages":["小豬正替稻草床拍枕頭，一下，兩下，拍出一朵金色的小雲。「上次牧草不夠，貝克替大家算好份量，還把自己的那份分給小羊。」","牠抱緊枕頭：「所以聽見貝克說打退野狼，我馬上就信了。可是我的肚子一直咕嚕響……這次不是餓，是害怕。你能陪我坐一下嗎？」"]}],"panicked":[{"pages":["小豬把鼻子藏進稻草，身子還露在外面。「不要告訴狼我在這裡！貝克親口說，牠差一點就回不來了。」","你輕聲喊牠的名字。兩隻耳朵終於轉向你：「你會陪我一起去看嗎？我一個人，什麼都不敢看了。」"]}],"comforted":{"pages":["你慢慢摸摸牠的頭，等急促的呼吸變得平穩。牠看向你：「謝謝你願意等。我們再把事情從頭想一遍吧。」","牠抱緊枕頭：「所以聽見貝克說打退野狼，我馬上就信了。可是我的肚子一直咕嚕響……這次不是餓，是害怕。你能陪我坐一下嗎？」"]},"injured":{"pages":["豬蜷在草地上，試著站起來，又輕輕坐回去。「這次真的受傷了……你看得見我嗎？」","你蹲下來，讓牠知道有人陪著。「我們回紅農舍上藥。路上慢慢走，其他的事等安全了再說。」"]},"post_rescue":{"pages":["暖暖的繃帶包好傷口，小豬終於肯放開你的衣角。「謝謝你真的回來找我。我剛才以為沒有人聽得到。」","牠把東南破牆的位置畫在地上：「這是我親眼看見的。以後我也想學會，把自己看見的事好好說清楚。」"]},"rumorResponse":{"pages":["{name}連忙抱住稻草枕頭：「你這麼會想辦法，都被狼弄傷，牠一定可怕極了！」","牠一路喊著「東門！東門！」，連最喜歡的泥坑也不敢去了。貝克望著牠的背影，嘴巴動了動，卻沒有把真話說出口。"]},"afterTruth":[{"pages":["豬望向正在道歉的貝克：「原來那條腿是跌進泥坑傷的。我剛才相信了，還把自己嚇得團團轉。」","你們一起把聽說的話和查到的事分開記。風又吹動草尖，大家重新聽見了農場原本的聲音。"]}]},"pigeon":{"name":"鴿子","nextCharacter":"sheep","normal":[{"pages":["信鴿把一本小筆記藏在翅膀下。「送信最怕把一句話傳成另一句。我出發前，會先問：這是你看見的，還是你聽說的？」","牠不好意思地低頭：「不過今天貝克說得太像真的，我也差點直接傳出去。你來得正好，我們一起核對昨晚的記錄吧。」"]}],"panicked":[{"pages":["信鴿叼著兩張不同的紙條，不知道先送哪一張。「大家都催我！可是傳錯了，會不會讓更多同伴跑錯地方？」","你把紙條放平。牠深深呼吸：「先陪我翻開原本的記錄。時間寫在那裡，不會因為誰喊得大聲就改變。」"]}],"comforted":{"pages":["你慢慢摸摸牠的頭，等急促的呼吸變得平穩。牠看向你：「謝謝你願意等。我們再把事情從頭想一遍吧。」","牠不好意思地低頭：「不過今天貝克說得太像真的，我也差點直接傳出去。你來得正好，我們一起核對昨晚的記錄吧。」"]},"injured":{"pages":["鴿子蜷在草地上，試著站起來，又輕輕坐回去。「這次真的受傷了……你看得見我嗎？」","你蹲下來，讓牠知道有人陪著。「我們回紅農舍上藥。路上慢慢走，其他的事等安全了再說。」"]},"post_rescue":{"pages":["信鴿在農舍裡攤開翅膀，確認筆記還在。「幸好紙沒有弄丟，也幸好你找到了我。」","牠把四個入口畫在同一張紙上：「等我能飛，再替大家送查證過的消息。現在，請你把它帶給需要的同伴。」"]},"rumorResponse":{"pages":["{name}急忙攤開紙條：「貝克負傷，狼要從東門來……我得趕快送出去！」","牠寫到一半停住，仍相信朋友受過狼的襲擊，卻還沒翻開自己的夜巡筆記。最需要核對的那一頁，被壓在最下面。"]},"afterTruth":[{"pages":["鴿子望向正在道歉的貝克：「原來那條腿是跌進泥坑傷的。我剛才相信了，還把自己嚇得團團轉。」","你們一起把聽說的話和查到的事分開記。風又吹動草尖，大家重新聽見了農場原本的聲音。"]}]},"sheep":{"name":"黑鼻羊・貝克","nextCharacter":"cow","normal":[{"pages":["貝克坐在石頭旁，把一片濕葉子從羊毛裡拔出來。「哎喲……你看，我只是不小心。不是，我是說，我昨晚太勇敢了！」","牠偷偷看你的表情，像在等一聲稱讚。你把水放在牠身旁：「先喝一口吧。我願意聽，你可以從頭慢慢說。」"]}],"rumor_spread":{"pages":["貝克抬起包著泥巴的腿：「昨晚野狼撲過來，我砰地踢回去，才保住大家！你看，這就是證明。」","「今晚一定要看東門！」牠把聲音放得更大，卻不敢望向北邊的泥坑。故事像滾下坡的雪球，越滾越大。"]},"panicked":[{"pages":["貝克躲在乾草後，聽見外面一聲接一聲喊狼。「我只想讓大家覺得我很勇敢，怎麼每個人都哭喪著臉……」","牠摸摸扭傷的腿：「現在說出泥坑的事，會不會太晚？可是繼續說下去，心裡更難受。」"]}],"injured":{"pages":["羊蜷在草地上，試著站起來，又輕輕坐回去。「這次真的受傷了……你看得見我嗎？」","你蹲下來，讓牠知道有人陪著。「我們回紅農舍上藥。路上慢慢走，其他的事等安全了再說。」"]},"post_rescue":{"pages":["貝克看著乾淨的繃帶，鼻尖一酸。「你聽了那麼多話，還是回來救我了。謝謝你。」","「昨晚的事……請先去問信鴿、鴨子和烏鴉，再來找我。我想把藏起來的那一段，也說給你聽。」"]},"afterTruth":[{"pages":["貝克把一籃莓果放在農舍前，這次是和同伴一起去採的。「我還是想幫忙，但不用把自己說成大英雄。」","牠看著你：「跌倒可以求救，說錯可以改口。下次我會先說『我還不確定』，也會把真話好好說完。」"]}],"rumorResponse":{"pages":["貝克抬起包著泥巴的腿：「昨晚野狼撲過來，我砰地踢回去，才保住大家！你看，這就是證明。」","「今晚一定要看東門！」牠把聲音放得更大，卻不敢望向北邊的泥坑。故事像滾下坡的雪球，越滾越大。"]},"comforted":{"pages":["你慢慢摸摸牠的頭，等急促的呼吸變得平穩。牠看向你：「謝謝你願意等。我們再把事情從頭想一遍吧。」","牠偷偷看你的表情，像在等一聲稱讚。你把水放在牠身旁：「先喝一口吧。我願意聽，你可以從頭慢慢說。」"]}},"sparrow":{"name":"麻雀","nextCharacter":"pigeon","normal":[{"pages":["麻雀把落葉排成一圈，正好圍住一顆小草籽。「這是我的小餐桌，你要不要坐旁邊？」","牠啾啾地說：「貝克說狼快來時，我連草籽都叼不住。可是我還記得昨晚果園的聲音。你願意聽小小的聲音嗎？」"]}],"panicked":[{"pages":["麻雀在兩根枝頭間飛來飛去。「這根太低，那根太細！貝克說狼很厲害，我找不到能安心站的地方。」","你在樹下等牠，沒有催。牠終於停住：「你在這裡，我就能把話說慢一點了。」"]}],"comforted":{"pages":["你慢慢摸摸牠的頭，等急促的呼吸變得平穩。牠看向你：「謝謝你願意等。我們再把事情從頭想一遍吧。」","牠啾啾地說：「貝克說狼快來時，我連草籽都叼不住。可是我還記得昨晚果園的聲音。你願意聽小小的聲音嗎？」"]},"injured":{"pages":["麻雀蜷在草地上，試著站起來，又輕輕坐回去。「這次真的受傷了……你看得見我嗎？」","你蹲下來，讓牠知道有人陪著。「我們回紅農舍上藥。路上慢慢走，其他的事等安全了再說。」"]},"post_rescue":{"pages":["麻雀縮在軟布裡，輕得像一片葉子。「你抱我的時候好小心，我一路都聽見你的腳步。」","牠用嘴尖指向南邊：「果園的草倒了一長條。請找同伴一起看看，我在這裡等你帶消息回來。」"]},"rumorResponse":{"pages":["{name}嚇得掉下嘴裡的草籽：「你那麼大都受傷了，我這麼小怎麼辦？」","牠飛起又落下，急著把話告訴下一位夥伴。草籽留在地上，沒有人記得剛才還在吃早餐。"]},"afterTruth":[{"pages":["麻雀望向正在道歉的貝克：「原來那條腿是跌進泥坑傷的。我剛才相信了，還把自己嚇得團團轉。」","你們一起把聽說的話和查到的事分開記。風又吹動草尖，大家重新聽見了農場原本的聲音。"]}]}},"branches":{"evidence":{"night_out":"信鴿記下：昨夜黑鼻羊獨自走出農舍，往北邊去了。","duck_shadow":"鴨子在池塘看見比狼還大的影子；這只能證明牠看見影子，不能證明是狼。","crow_tracks":"烏鴉親眼看見：貝克採莓果時滑進北邊泥坑，受傷時沒有狼在旁邊；另一段路才有狼爪印。","sheep_truth":"三份證詞對上了：貝克承認泥坑跌傷，編成與狼搏鬥；狼的入口仍須分別查證。"},"clues":{"north":"北方：臭水溝有狼爪印，可能是入口。","west":"西方：木門下有新鮮狼味。","southeast":"東南方：矮圍牆有可鑽入的破洞。","south":"南方：廢果園的草叢被壓倒。"},"rescueGrants":{"pig":["southeast"],"cow":["north"],"horse":["west"],"dog":["west"],"chicken":["south"],"crow":["north"],"sparrow":["south"]},"conversations":{"sheep":[{"id":"sheep-claim","route":"truth","nextCharacter":"pigeon","pages":["晨光灑在草尖上，黑鼻羊貝克卻把一條腿高高抬起。牠看見你，立刻挺起胸膛：「噓——靠近一點。我昨晚做了一件了不起的大事！」","「一頭狼從樹後跳出來，牙齒像兩排白石頭！我轉身、踢腿，砰！牠就滾進草叢了！」貝克說得好響，腿卻悄悄往身後縮。羊毛裡還黏著一片濕葉子。","你蹲下來：「所以，你的腿是在打架時受傷的？」貝克眨了兩下眼睛。「當、當然！狼今晚只會從東門來。你去問信鴿吧……牠一定看見我多勇敢！」","一陣風送來莓果的甜味。貝克趕緊把沾著紫色汁水的嘴角擦乾淨，轉身喊道：「大家都該知道這件事！」牠一拐一拐，朝第一位同伴走去。"]},{"id":"sheep-confession","route":"truth","requires":["night_out","duck_shadow","crow_tracks"],"grants":["sheep_truth","north"],"nextCharacter":"dog","pages":["你把三份證詞放在草地上：信鴿的時間、鴨子看見的影子，還有烏鴉親眼看見的泥坑。貝克低下頭，鼻尖幾乎碰到自己的蹄子。","「我沒有和狼打架。」牠的聲音比草葉摩擦還輕。「我偷偷去採莓果，想帶一大把回來讓大家誇獎我。可是泥巴一滑——噗通！腿就扭到了。」","「烏鴉問要不要幫忙，我還叫牠別說出去。天亮後，大家都圍過來，我怕被笑，就把泥坑說成了野狼……越說越大，連我自己也不知道怎麼停。」","你說：「我們可以照顧受傷的你，也需要知道真正發生的事。」貝克吸了吸鼻子，向同伴道歉：「東門只是我猜的。北邊確實有狼腳印，我們一起去查，好嗎？」"]}],"pig":[{"id":"pig-wall","route":"defense","grants":["southeast"],"nextCharacter":"dog","pages":["小豬把鼻子埋進稻草，露出兩隻圓耳朵。「貝克上次幫大家分牧草，連最小的羊都沒餓到。牠說的話，我一直很相信。」","你陪牠慢慢呼吸。小豬終於抬頭：「不過，我親眼看見的，是東南矮牆破了一個洞。昨天還沒有呢！牆邊有毛，泥土也被踩鬆了。」","你們把破洞畫進筆記。小豬拍拍肚皮：「這個可以一起去看。狗的鼻子最靈，請牠也聞聞看！」"]}],"cow":[{"id":"cow-north","route":"defense","grants":["north"],"nextCharacter":"crow","pages":["乳牛站在風裡，脖子上的鈴鐺輕輕響。「貝克的腿腫了，我一看就信了牠。可是，害怕的時候，我連風吹樹葉都聽成狼叫。」","牠帶你聞一聞北邊吹來的風：「這股味道和從前狼靠近時很像。我還沒看見狼，所以不能說一定是牠；北渠值得查一查。」","你在地圖北邊畫個圈。乳牛望向天空：「烏鴉站得高，也許看見了我們看不見的事。去問問牠吧。」"]}],"horse":[{"id":"horse-west","route":"defense","grants":["west"],"nextCharacter":"dog","pages":["馬兒的蹄子噠、噠、噠，在西門前停下。「聽說貝克踢跑一頭狼，我還練了一早上的踢腿！可是我的心，跳得比蹄子還快。」","你指向門邊。牠低頭說：「木門下面的土被刨開了，這是我今天巡路看見的。我沒有看見誰挖的，可得請狗來聞一聞。」","馬兒用鼻尖輕碰你的肩膀：「我可以替你多跑一趟。請別只聽『東門』兩個字，就忘記其他地方呀。」"]}],"dog":[{"id":"dog-patrol","route":"defense","grants":["west","dog_patrol"],"nextCharacter":"pigeon","pages":["牧羊犬托托把耳朵豎成兩面小旗。「連貝克都受傷，我當然擔心！不過鼻子告訴我的事，得和耳朵聽來的分開記。」","牠沿西門底下聞了又聞：「這裡有新鮮狼味。我會沿著圍欄巡邏，夜裡若有狼靠近，就先把牠引開，替同伴爭取時間。」","托托抖抖毛，向你搖尾巴：「汪！你去找信鴿記下昨晚的時間。我去守路，我們各做一件能幫忙的事。」"]},{"id":"dog-doubt","route":"truth","requires":["night_out"],"nextCharacter":"crow","pages":["托托湊近貝克留下的泥點，鼻子輕輕抽動。「這是北渠的濕泥。我聞得到泥巴，卻聞不到牠身上有和狼纏鬥的味道。」","你問：「所以貝克一定說謊嗎？」托托搖頭：「鼻子也有不知道的事。先別急著下結論，還要問親眼看見的夥伴。」","牠把頭轉向北邊的樹：「烏鴉昨夜醒著。你可以問牠：貝克受傷的那一刻，你究竟看見了什麼？」"]}],"cat":[{"id":"cat-warning","route":"defense","nextCharacter":"chicken","pages":["貓咪從窗臺跳下來，尾巴像一個問號。「大家都在喊狼，我也把爪子縮得緊緊的。可是受傷的夥伴，需要的是幫忙。」","牠推來一卷繃帶：「夜裡受傷，要趕快抱回紅農舍；兩回合內一定要治療。網夾只有五個，用壞了就不能修，放之前得先查清入口。」","你收好繃帶。貓咪把路讓出來：「去看看雞媽媽吧。牠守著南邊雞舍，一整夜都沒有睡好。」"]}],"chicken":[{"id":"chicken-south","route":"defense","grants":["south"],"nextCharacter":"sparrow","pages":["雞媽媽把小雞攏在翅膀下，咯咯聲比平常低了許多。「貝克說狼很大，我就一直數孩子。數一遍，再數一遍，總怕少了一隻。」","你陪牠數完，牠才想起：「昨夜南邊廢果園傳來沙沙聲。天亮去看，草被壓倒了一長條。聲音是什麼，我沒看清楚。」","牠把一根草莖交給你：「麻雀住在那附近，也許能補上我沒看見的那一頁。」"]}],"duck":[{"id":"duck-monster","route":"truth","grants":["duck_shadow"],"nextCharacter":"crow","pages":["鴨子把腳掌拍得啪嗒啪嗒響。「昨晚池塘裡有個大怪物！頭上長角，身子高過樹，我嚇得把嘴巴都藏進翅膀裡！」","你問：「你看見牠站在岸上嗎？」鴨子愣住了。「只有水裡的影子……月亮在後面，水又一直晃。咦，岸上好像還有一聲『哎喲』！」","「影子大，不一定身體也大。」你在筆記上畫了波紋。鴨子點點頭：「我只知道這些。烏鴉昨晚在北邊，牠也許看得更清楚。」"]},{"id":"duck-water","route":"defense","nextCharacter":"goose","pages":["池塘邊的蘆葦沙沙搖。鴨子指著一道水痕：「我差點又喊狼來了，可是我自己游過去，也會留下水痕呀。」","你問牠還記得什麼。鴨子歪頭想：「貝克告訴我東門有狼，我就把每個影子都當成狼。現在我想先把看見的、聽來的分開。」","牠抖掉羽毛上的水珠：「去問守池塘的鵝吧。也請你記住，我昨晚沒有看清岸上的動物。」"]}],"goose":[{"id":"goose-doubt","route":"truth","requires":["duck_shadow"],"nextCharacter":"crow","pages":["大鵝把翅膀張開，替慌張的鴨子擋住風。「牠真的嚇壞了。我聽完貝克的故事，也以為池塘外全是狼。」","你們再看水面：一根蘆葦，被月光拉成長長的黑影。大鵝輕聲說：「原來影子會把小東西畫得這麼大。害怕是真的，怪物還沒有證實。」","「我們去找烏鴉。」大鵝把翅膀收回來。「牠在空中看到的，或許能把這幅歪歪的圖拼好。」"]}],"crow":[{"id":"crow-tracks","route":"truth","requires":["night_out"],"grants":["crow_tracks","north","crow_guard"],"nextCharacter":"sheep","pages":["烏鴉落在矮枝上，歪頭看你。「你要問貝克的腿？嘎，我親眼看見的可不是英勇大戰。昨晚，月亮正好照亮北邊的泥坑。」","「牠嘴裡含著莓果，蹄子踩上濕苔——溜！噗通！泥巴飛得比牠的角還高。我問：『要拉你一把嗎？』牠卻喊：『別告訴大家！』」","烏鴉拍拍翅膀：「那時根本沒有狼碰牠。後來我才在另一段路看見狼爪印。我還飛下去逗那頭狼；牠一跳，我就飛高：『你不會飛，打不到我！嘎嘎！』」","你問牠願不願意作證。烏鴉收起笑聲：「願意。笑完也要幫忙。把信鴿的時間和鴨子的影子對一對，再請貝克自己把故事說完。我今晚也會飛著牽制野狼。」"]},{"id":"crow-watch","route":"defense","grants":["north","crow_guard"],"nextCharacter":"pigeon","pages":["烏鴉站在圍欄尖上，胸膛挺得像個小隊長。「別的動物怕狼，我偏要去跟牠比一比！嘎，當然要用我的本領。」","牠往下一俯衝，立刻又飛回枝頭。「狼撲來，我就飛高！『你不會飛，打不到我！』不過，你可別學我；沒有翅膀，要留在安全的地方。」","牠望向北渠：「那裡有狼爪印，是真的。我也看見貝克昨晚的事。先去問信鴿時間，再來找我，我會仔細說給你聽。」"]}],"sparrow":[{"id":"sparrow-orchard","route":"defense","grants":["south"],"nextCharacter":"pigeon","pages":["小麻雀把一顆草籽放到你鞋尖。「本來想送給雞媽媽，可是大家一喊狼，我也嚇得忘記怎麼唱歌了。」","你坐在樹下等牠。牠終於說：「昨晚南邊廢果園有重重的腳步；今天草倒了一排。我看不見腳步的主人，只能告訴你在哪裡。」","你把草籽收進口袋。小麻雀又啾了一聲：「請信鴿把地點記好。這回，我們慢慢說，讓大家聽清楚。」"]}],"pigeon":[{"id":"pigeon-record","route":"truth","grants":["night_out"],"nextCharacter":"duck","pages":["信鴿打開翅膀下的小本子。紙角捲捲的，像曬乾的葉片。「我也聽信了貝克，差點把『羊狼大戰』送到整座農場。」","牠用嘴尖指著一行記號：「可是我的夜巡筆記只寫著：月亮剛升起，貝克獨自往北走；天快亮時，牠滿身泥回來。中間發生什麼，我沒有看見。」","你問：「有人能補上嗎？」信鴿點頭：「鴨子昨晚醒過一次，烏鴉也在北邊。我的筆記能記時間，不能替沒有看見的事情作證。」"]},{"id":"pigeon-routes","route":"defense","nextCharacter":"pig","pages":["信鴿攤開地圖，用四顆小石子壓住紙角。「北渠、西門、東南破牆、南果園。我們一處一處記，別讓一個響亮的故事蓋住整張地圖。」","你把聽來的話畫成小耳朵，親眼看見的事畫成小眼睛。信鴿笑了：「這樣，大家就知道哪一件還要查。」","牠把地圖交給你：「小豬發現了一個破洞。去聽牠說位置，查證後再決定網夾放哪裡。」"]}]}}};
